import numpy as np
lines = open('built.xyz').read().split('\n')
n = int(lines[0])
els, xyz = [], []
for l in lines[2:2+n]:
    p = l.split()
    els.append(p[0]); xyz.append([float(x) for x in p[1:4]])
xyz = np.array(xyz)
cov = {'H':0.31,'C':0.76,'N':0.71,'Ga':1.22,'Ni':1.24}
bad = []
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(xyz[i]-xyz[j])
        r = cov[els[i]]+cov[els[j]]
        if d < 0.75*r:
            bad.append((i,j,els[i],els[j],round(d,2)))
print("close contacts (<0.75*covsum):")
for b in bad: print(b)
# list nonbonded contacts between 0.75 and 0.95 covsum
print("moderate:")
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(xyz[i]-xyz[j])
        r = cov[els[i]]+cov[els[j]]
        if 0.75*r <= d < 0.9*r:
            print(i,j,els[i],els[j],round(d,2))
